INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(35261, 'Exodus 23:17', 'Exodus', 23, 17, 'هر کال باید په دغو درېو اخترونو کې ستاسو ټول نارینه زما یعنې ستاسو د څښتن تعالی د عبادت دپاره راشي.', 'هر کال باید په دغو درېو اخترونو کې ستاسو تول نارینه زما یعنې ستاسو د چشتن تعالی د عبادت دپاره راشی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_23_17.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35262, 'Exodus 23:18', 'Exodus', 23, 18, 'کله چې تاسو ماته یو حیوان قرباني کوئ، د هغه سره خمیره ډوډۍ مه وړاندې کوئ. هغه حیوانات چې په دغو اخترونو کې ماته قرباني کیږي، د هغې وازګه باید تر سهاره پورې پاتې نه شي.', 'کله چې تاسو ماته یو حیوان قربانی کوی، د هغه سره خمیره دودی مه وراندې کوی. هغه حیوانات چې په دغو اخترونو کې ماته قربانی کیزی، د هغې وازګه باید تر سهاره پورې پاتې نه شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_23_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35263, 'Exodus 23:19', 'Exodus', 23, 19, 'هر کال د خپل څښتن خدای کور ته د خپل لومړني حاصل ډېرې ښې غلې دانې راوړئ. یو سېرلی د خپلې مور په شیدو کې مه پخوئ.', 'هر کال د خپل چشتن خدای کور ته د خپل لومرنی حاصل دېرې شې غلې دانې راوری. یو سېرلی د خپلې مور په شیدو کې مه پخوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_23_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35264, 'Exodus 23:20', 'Exodus', 23, 20, 'ګورئ، زه ستاسو مخې ته یوه فرښته درلېږم چې په لاره کې ستاسو ساتنه وکړي او هغه ځای ته مو راولي چې ستاسو دپاره مې تیار کړی دی.', 'ګوری، زه ستاسو مخې ته یوه فرشته درلېزم چې په لاره کې ستاسو ساتنه وکری او هغه جای ته مو راولی چې ستاسو دپاره مې تیار کری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_23_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35265, 'Exodus 23:21', 'Exodus', 23, 21, 'هرڅه چې هغه فرښته وایي په غور سره ورڅخه اطاعت وکړئ. د هغې په وړاندې سرکښي مه کوئ، هغه به ستاسو سرکښي ونه بخښي، ځکه چې پوره اختیار مې ورته ورکړی دی.', 'هرچه چې هغه فرشته وایی په غور سره ورچخه اطاعت وکری. د هغې په وراندې سرکشی مه کوی، هغه به ستاسو سرکشی ونه بخشی، جکه چې پوره اختیار مې ورته ورکری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_23_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35266, 'Exodus 23:22', 'Exodus', 23, 22, 'که چېرې تاسو په غور سره د هغې خبرو ته غوږ ونیسئ او هرڅه چې زه درته وایم هغه وکړئ، نو زه به ستاسو د دښمنانو دښمن شم او زه به د هغه چا په خلاف شم چې ستاسو په خلاف وي.', 'که چېرې تاسو په غور سره د هغې خبرو ته غوز ونیسی او هرچه چې زه درته وایم هغه وکری، نو زه به ستاسو د دشمنانو دشمن شم او زه به د هغه چا په خلاف شم چې ستاسو په خلاف وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_23_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35267, 'Exodus 23:23', 'Exodus', 23, 23, 'زما فرښته به ستاسو په مخکې روانه وي او تاسو به د اموریانو، حیتیانو، فرزیانو، کنعانیانو، حویانو او یبوسیانو خاورې ته بوځي او زه به هغوی ټول له منځه یوسم.', 'زما فرشته به ستاسو په مخکې روانه وی او تاسو به د اموریانو، حیتیانو، فرزیانو، کنعانیانو، حویانو او یبوسیانو خاورې ته بوجی او زه به هغوی تول له منجه یوسم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_23_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35268, 'Exodus 23:24', 'Exodus', 23, 24, 'د هغوی خدایانو ته سجده یا عبادت مه کوئ او د هغوی د رواجونو څخه پیروي مه کوئ. د هغوی بتان له منځه یوسئ او هغه لویې تیږې چې د هغوی د عبادت دپاره ورڅخه کار اخیستل کیږي، ټوټې ټوټې کړئ.', 'د هغوی خدایانو ته سجده یا عبادت مه کوی او د هغوی د رواجونو چخه پیروی مه کوی. د هغوی بتان له منجه یوسی او هغه لویې تیزې چې د هغوی د عبادت دپاره ورچخه کار اخیستل کیزی، توتې توتې کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_23_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35269, 'Exodus 23:25', 'Exodus', 23, 25, 'که چېرې تاسو زما یعنې د خپل څښتن خدای عبادت وکړئ، نو زه به ستاسو په خوراک او اوبو کې برکت واچوم او ستاسو ټولې ناروغۍ به لېرې کړم.', 'که چېرې تاسو زما یعنې د خپل چشتن خدای عبادت وکری، نو زه به ستاسو په خوراک او اوبو کې برکت واچوم او ستاسو تولې ناروغی به لېرې کرم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_23_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35270, 'Exodus 23:26', 'Exodus', 23, 26, 'ستاسو په خاوره کې به هېڅ یوه ښځه خپل اولاد نقصان نه کړي او نه به شنډه شي. زه به تاسو ته اوږده عمرونه درکړم.', 'ستاسو په خاوره کې به هېچ یوه شجه خپل اولاد نقصان نه کری او نه به شنده شی. زه به تاسو ته اوزده عمرونه درکرم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_23_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35271, 'Exodus 23:27', 'Exodus', 23, 27, 'زه به په هغو قومونو باندې سخته وېره راولم او ستاسو دښمنان به دومره وارخطا کړم چې درڅخه وتښتي.', 'زه به په هغو قومونو باندې سخته وېره راولم او ستاسو دشمنان به دومره وارخطا کرم چې درچخه وتشتی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_23_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35272, 'Exodus 23:28', 'Exodus', 23, 28, 'زه به ستاسو په دښمنانو کې سخته وېره پیدا کړم او حویان، کنعانیان او حیتیان به ستاسو له مخې څخه لېرې کړم.', 'زه به ستاسو په دشمنانو کې سخته وېره پیدا کرم او حویان، کنعانیان او حیتیان به ستاسو له مخې چخه لېرې کرم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_23_28.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35273, 'Exodus 23:29', 'Exodus', 23, 29, 'خو زه به هغوی په یو کال کې ونه باسم، ځکه چې ځمکه به ویجاړه پاتې شي او وحشي حیوانات به ډېر زیات شي.', 'خو زه به هغوی په یو کال کې ونه باسم، جکه چې جمکه به ویجاره پاتې شی او وحشی حیوانات به دېر زیات شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_23_29.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35274, 'Exodus 23:30', 'Exodus', 23, 30, 'بلکې هغوی به لږ لږ شړم، ترڅو تاسو دومره ډېر شئ چې هغه خاوره ونیسئ.', 'بلکې هغوی به لز لز شرم، ترچو تاسو دومره دېر شی چې هغه خاوره ونیسی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_23_30.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35275, 'Exodus 23:31', 'Exodus', 23, 31, 'زه به ستاسو د خاورې سرحدونه د سرې بحیرې څخه نیولې د مدیترانې تر بحیرې پورې او د دښتې څخه نیولې د فرات تر سینده پورې وغزوم. زه به تاسو سره مرسته وکړم چې هغو خلکو ته چې اوس په دې خاوره کې اوسیږي، ماتې ورکړئ او هغوی به وشړئ.', 'زه به ستاسو د خاورې سرحدونه د سرې بحیرې چخه نیولې د مدیترانې تر بحیرې پورې او د دشتې چخه نیولې د فرات تر سینده پورې وغزوم. زه به تاسو سره مرسته وکرم چې هغو خلکو ته چې اوس په دې خاوره کې اوسیزی، ماتې ورکری او هغوی به وشری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_23_31.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35276, 'Exodus 23:32', 'Exodus', 23, 32, 'د هغوی یا د هغوی د خدایانو سره هېڅ ډول تړون مه کوئ.', 'د هغوی یا د هغوی د خدایانو سره هېچ دول ترون مه کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_23_32.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35277, 'Exodus 23:33', 'Exodus', 23, 33, 'هغوی مه پرېږدئ چې ستاسو په هېواد کې واوسیږي. که چېرې تاسو هغوی پرېږدئ، هغوی به تاسو زما په ضد په ګناه کولو باندې مجبور کړي. که چېرې تاسو د هغوی د خدایانو عبادت وکړئ، نو دا به ستاسو دپاره یو وژونکی دام وي.»', 'هغوی مه پرېزدی چې ستاسو په هېواد کې واوسیزی. که چېرې تاسو هغوی پرېزدی، هغوی به تاسو زما په ضد په ګناه کولو باندې مجبور کری. که چېرې تاسو د هغوی د خدایانو عبادت وکری، نو دا به ستاسو دپاره یو وژونکی دام وی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_23_33.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237838, 1761237838),
(35278, 'Psalms 100:1', 'Psalms', 100, 1, 'ای ټولې نړۍ، څښتن ته ووهئ د خوشحالۍ چیغې', 'ای تولې نری، چشتن ته ووهی د خوشحالی چیغې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_100_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35279, 'Psalms 100:2', 'Psalms', 100, 2, 'وکړئ عبادت د څښتن خدای په خوشحالۍ سره په سندرو د خوښۍ د هغه حضور ته راشئ', 'وکری عبادت د چشتن خدای په خوشحالی سره په سندرو د خوشی د هغه حضور ته راشی', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_100_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35280, 'Psalms 100:3', 'Psalms', 100, 3, 'ومنئ دا چې څښتن خدای دی مونږ یو خلق کړي هغه او د هغه یو مونږه مونږ یو خلک د هغه او رمه یې د څړځای یو', 'ومنی دا چې چشتن خدای دی مونز یو خلق کری هغه او د هغه یو مونزه مونز یو خلک د هغه او رمه یې د چرجای یو', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_100_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35281, 'Psalms 100:4', 'Psalms', 100, 4, 'شکر کولو سره ننوځئ د هغه دروازو ته د هغه عبادتځای ته د ثنا سره ورننوځئ شکر یې ادا کړئ او صفت یې د نامه وکړئ', 'شکر کولو سره ننوجی د هغه دروازو ته د هغه عبادتجای ته د ثنا سره ورننوجی شکر یې ادا کری او صفت یې د نامه وکری', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_100_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35282, 'Psalms 100:5', 'Psalms', 100, 5, 'ځکه څښتن دی نېک او ده ابدي د هغه مینه وفاداري یې ده جاري د یو نسل نه تر بله پورې', 'جکه چشتن دی نېک او ده ابدی د هغه مینه وفاداری یې ده جاری د یو نسل نه تر بله پورې', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Psalms_100_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35283, 'Nahum 2:1', 'Nahum', 2, 1, 'ای نینوا، ته د حملې لاندې یې وساته خپلې جنګي کلاوې وڅاره لارې، جنګ ته تیار اوسه کړه راټول خپل قوتونه', 'ای نینوا، ته د حملې لاندې یې وساته خپلې جنګی کلاوې وچاره لارې، جنګ ته تیار اوسه کره راتول خپل قوتونه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_2_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35284, 'Nahum 2:2', 'Nahum', 2, 2, 'څښتن به د اسراییلو هغه شان او شوکت چې دښمنانو یې له منځه وړی ؤ، لکه د یهودا د شان او شوکت په شان بېرته ورته راولي.', 'چشتن به د اسراییلو هغه شان او شوکت چې دشمنانو یې له منجه وری و، لکه د یهودا د شان او شوکت په شان بېرته ورته راولی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_2_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
(35285, 'Nahum 2:3', 'Nahum', 2, 3, 'راروان کړي د دښمن لښکرو سره سپرونه د هغه عسکرو دی اغوستی سور لباس ځلیږي په ګاډیو لګېدلی فلز په هغه ورځ چې کړي تیار هغوی نو عسکر به کړي راپورته خپلې نېزې او خوځوي به هغه', 'راروان کری د دشمن لشکرو سره سپرونه د هغه عسکرو دی اغوستی سور لباس جلیزی په ګادیو لګېدلی فلز په هغه ورج چې کری تیار هغوی نو عسکر به کری راپورته خپلې نېزې او خوجوی به هغه', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Nahum_2_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237838, 1761237838),
